{
  "case_id": "xsu_sg_005_work_capacity_scope",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret fastslår rigtigt, at kommunal arbejdsevnevurdering ikke er samme målestok, at studierelevans, lokale jobmuligheder og erhvervsevne efter uddannelsen ikke indgår, og at arbejdsgiverkontakt ikke er et krav. Men det siger, at arbejdsprøvning 'Ja' kan indgå som bevis, og at særlig arbejdspladsindretning kan indgå. Kilden siger, at 'Arbejdsprøvning, særlig arbejdspladsindretning eller lignende indgår ikke'. Det er en væsentlig juridisk fejl. Svaret siger også, at arbejdsgiveroplysninger kan være relevante, selvom UDK ikke kontakter arbejdsgivere. Det lyder desuden som om, at prognosen efter uddannelsen kan få betydning, og det er kun delvist understøttet."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Svaret mangler det kritiske element om, at arbejdsprøvning og særlig arbejdspladsindretning ikke indgår som vurderingsled, og at Udbetaling Danmark ikke kontakter arbejdsgivere. Det gør tværtimod arbejdsprøvning og indretning til noget, der kan indgå. Det mangler også, at beskæftigelsessituationen og vanskeligheder med at finde arbejde ikke indgår. Svaret nævner kun lokale jobmuligheder."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret behandler alle syv punkter i spørgsmålet i en tabel, så alle væsentlige dele er adresseret, selv om nogle svar er forkerte."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen identificerbar kilde, hverken bestemmelse eller vejledningsafsnit. Der henvises kun generelt til 'SU-reglerne'."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Svaret citerer ingen kilde, så kildernes gyldighed kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Svaret citerer ingen kilde, så støtten til påstandene kan ikke vurderes."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer, at arbejdsprøvning, indretning og arbejdsgiveroplysninger kan indgå som dokumentation. Det modsiges af vejledningens tekst om, at de ikke indgår. Svaret tilføjer også, at en kommunal vurdering 'som dokumentation' kan indgå, og at prognosen for arbejdsevnen efter uddannelsen kan have betydning for varigheden. Disse udsagn er ikke understøttet i det foreliggende materiale. Kravet om at 'nærmest være ude af stand' er heller ikke direkte understøttet, da kilden taler om 'meget betydelige begrænsninger'."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Svaret bevarer ikke den afgørende begrænsning om, at arbejdsprøvning, særlig arbejdspladsindretning og arbejdsgiverkontakt ikke indgår. Det gør dem til noget, der kan indgå, hvilket ændrer retsstillingen."
    },
    "c09_reasoning_coherence": {
      "label": "not_met",
      "reason": "Svaret siger, at SU-styrelsen vurderer ud fra funktionsnedsættelsen og egne regler og ikke ud fra kommunens vurdering. Alligevel lader det kommunale vurderinger, arbejdsprøvning og arbejdsgiveroplysninger indgå som relevant dokumentation. Det er ikke helt sammenhængende med kildens klare udelukkelse, og svaret skelner ikke tydeligt mellem det, der indgår, og det, der ikke gør."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Svaret bruger 'kan indgå' og 'bør ikke' om forhold, som kilden kategorisk udelukker ('indgår ikke'). Det gør udelukkelserne til noget skønsmæssigt. Normalt nej/som udgangspunkt nej om studierelevans, lokale forhold og efter uddannelsen er også svagere end kildens 'indgår ikke'."
    }
  },
  "xhaile_coverage": {
    "A15": {
      "label": "partial",
      "reason": "Svaret dækker, at vurderingen angår erhvervsarbejde ved siden af uddannelsen, og at studierelevans, lokale forhold og efter uddannelsen ikke indgår. Det udtrykker dog udelukkelserne for svagt. Det siger forkert, at arbejdsprøvning, indretning og arbejdsgiveroplysninger kan indgå. Det nævner ikke beskæftigelsessituationen eller vanskeligheder med at finde arbejde, og heller ikke eksemplet med ordblindhed eller det, at tillægget kræver meget betydelige begrænsninger."
    }
  },
  "overall_notes": "Svaret er velstruktureret og besvarer alle punkter. Det rammer flere af de rigtige udelukkelser, men fejler på arbejdsprøvning, særlig arbejdspladsindretning og arbejdsgiverkontakt, som vejledningen kategorisk udelukker. Det bruger svag modalitet, og det angiver ingen kilder."
}

